async placeOrder({ sku, token }) {
  if (!sku || !token) return { status: 400, error: 'Missing product or payment token' };
  if (!store.reserve(sku)) return { status: 409, error: 'Out of stock' };

try {
  const receipt = await payment(token);
  const order = store.saveOrder(sku, receipt);
  return { status: 201, order };
} catch {
  store.release(sku);
  return { status: 402, error: 'Payment declined' };

reserve(sku) {
  const quantity = this.stock.get(sku) || 0;
  if (quantity < 1) return false;
  this.stock.set(sku, quantity - 1);
  return true;
}

saveOrder(sku, receipt) {
  const order = { id: `order-${this.orders.length + 1}`, sku, receipt };
  this.orders.push(order);
  return order;
}

export async function charge(token) {
  if (token === 'declined') throw new Error('Payment declined');
  return { id: 'receipt-demo', status: 'paid' };
}
